package main

import (
	"fmt"
	"io/fs"
	"log"
	"os"
	"path/filepath"
)

func main() {
	// Build a small tree to look at. os functions accept "/" on Windows too.
	for _, name := range []string{
		"data/İzmir.txt", "data/Zonguldak.txt", "data/notlar.md",
		"data/raporlar/Ocak.csv", "data/raporlar/Şubat.csv",
		"data/node_modules/lib/index.js",
	} {
		if err := os.MkdirAll(filepath.Dir(name), 0o755); err != nil { // mkdir -p
			log.Fatal(err)
		}
		if err := os.WriteFile(name, []byte("x"), 0o644); err != nil {
			log.Fatal(err)
		}
	}

	entries, err := os.ReadDir("data") // one level, sorted by name as bytes
	if err != nil {
		log.Fatal(err)
	}
	for _, e := range entries {
		fmt.Printf("dir=%-5t %s\n", e.IsDir(), e.Name())
	}

	err = filepath.WalkDir("data", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err // an unreadable directory: stop, or log it and return nil
		}
		if d.IsDir() && d.Name() == "node_modules" {
			return fs.SkipDir // don't descend
		}
		if filepath.Ext(path) == ".csv" {
			fmt.Println("walk:", filepath.ToSlash(path))
		}
		return nil
	})
	if err != nil {
		log.Fatal(err)
	}

	// The io/fs view of the same tree: relative, always "/"-separated names.
	matches, err := fs.Glob(os.DirFS("data"), "raporlar/*.csv")
	fmt.Println("glob:", matches, err)
}

files.examples/02_path_filepath.go:
package main

import (
	"fmt"
	"path"
	"path/filepath"
)

func main() {
	// path: "/"-separated names that aren't OS paths: URLs, embed.FS, io/fs, zip entries.
	fmt.Println(path.Join("/static", "css", "../img", "logo.png"))
	fmt.Println(path.Dir("raporlar/2026/Şubat.csv"), path.Base("/api/v1/users/"), path.Ext("yedek.tar.gz"))

	// filepath: the OS's paths, with "\" on Windows. ToSlash keeps this output portable.
	p := filepath.Join("data", "raporlar", "Şubat.csv")
	rel, err := filepath.Rel("data", p)
	fmt.Println(filepath.ToSlash(p), filepath.ToSlash(rel), err)

	// Join cleans "..", it doesn't confine: a user-supplied name climbs right out.
	fmt.Println(filepath.ToSlash(filepath.Join("uploads", "../../etc/passwd")))

	// IsLocal is the lexical check for names from users, archives and URLs.
	for _, name := range []string{"raporlar/Şubat.csv", "a/../b", "../secret.env", "a/../../b", "/etc/passwd", ""} {
		fmt.Printf("IsLocal(%q) = %t\n", name, filepath.IsLocal(name))
	}

	// Localize turns a "/" path (from a URL or an fs.FS) into an OS path, or refuses.
	for _, name := range []string{"raporlar/Şubat.csv", "../secret.env"} {
		local, err := filepath.Localize(name)
		fmt.Printf("Localize(%q) = %q, %v\n", name, filepath.ToSlash(local), err)
	}
}

files.examples/03_os_root.go:
package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
)

func main() {
	// A private file next to the upload directory.
	if err := os.WriteFile("secret.env", []byte("DB_PASSWORD=hunter2"), 0o600); err != nil {
		log.Fatal(err)
	}
	if err := os.Mkdir("uploads", 0o755); err != nil {
		log.Fatal(err)
	}

	root, err := os.OpenRoot("uploads") // every name below resolves inside uploads/
	if err != nil {
		log.Fatal(err)
	}
	defer root.Close()

	// MkdirAll, WriteFile and ReadFile on Root arrived in Go 1.25.
	if err := root.MkdirAll("2026/kasım", 0o755); err != nil {
		log.Fatal(err)
	}
	if err := root.WriteFile("2026/kasım/fatura.txt", []byte("tutar=1.250,50"), 0o644); err != nil {
		log.Fatal(err)
	}

	// Names as they might arrive in an HTTP request.
	for _, name := range []string{"2026/kasım/fatura.txt", "../secret.env", "2026/../../secret.env"} {
		naive, _ := os.ReadFile(filepath.Join("uploads", name))
		safe, err := root.ReadFile(name)
		fmt.Printf("%q IsLocal=%t\n", name, filepath.IsLocal(name))
		fmt.Printf("  os.ReadFile(Join): %q\n", naive)
		fmt.Printf("  root.ReadFile:     %q %v\n", safe, err)
	}
}
